<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue';
import { Head } from '@inertiajs/vue3';
import ErpLayout from '@/layouts/ErpLayout.vue';
import { useAuthorization } from '@/composables/useAuthorization';
interface Props { userName?: string; userEmail?: string }
interface OrderItem { id: number; product_name: string; variant_name?: string; sku?: string; quantity: string; unit_price: string; returnable_quantity: number }
interface Order { id: number; order_number: string; customer_name: string; location_id: number; items: OrderItem[] }
interface CashAccount { id: number; code: string; name: string }
interface ReturnRecord { id: number; return_number: string; return_date: string; refund_amount: string; refund_method: string; status: string; order?: { order_number: string; customer_name: string }; journal_entry?: { entry_number: string; status: string } }
const props = withDefaults(defineProps<Props>(), { userName: '', userEmail: '' });
const { can } = useAuthorization();
const orders = ref<Order[]>([]); const cashAccounts = ref<CashAccount[]>([]); const records = ref<ReturnRecord[]>([]);
const loading = ref(false); const saving = ref(false); const error = ref(''); const success = ref('');
const form = reactive({ sales_order_id: '', return_date: new Date().toISOString().slice(0,10), refund_method: 'cash', cash_account_id: '', reason: '', quantities: {} as Record<number,string> });
const selectedOrder = computed(() => orders.value.find(o => String(o.id) === form.sales_order_id));
const total = computed(() => (selectedOrder.value?.items ?? []).reduce((sum, item) => sum + Number(form.quantities[item.id] || 0) * Number(item.unit_price), 0));
const csrf = () => decodeURIComponent(document.cookie.split('; ').find(v => v.startsWith('XSRF-TOKEN='))?.split('=').slice(1).join('=') ?? '');
async function api<T>(url: string, options: RequestInit = {}): Promise<T> { const r = await fetch(url,{credentials:'same-origin',...options,headers:{Accept:'application/json','X-Requested-With':'XMLHttpRequest',...(options.body?{'Content-Type':'application/json','X-XSRF-TOKEN':csrf()}:{}),...(options.headers??{})}}); const p=await r.json().catch(()=>({})); if(!r.ok) throw new Error(p.message||Object.values(p.errors??{}).flat().join(' ')||`Request failed (${r.status})`); return p as T; }
async function load(): Promise<void> { loading.value=true; error.value=''; try { const [o,r]=await Promise.all([api<{data:Order[];cash_accounts:CashAccount[]}>('/api/sales-returns/options'),api<{data:ReturnRecord[]}>('/api/sales-returns?per_page=50')]); orders.value=o.data; cashAccounts.value=o.cash_accounts; records.value=r.data; if(!form.cash_account_id&&cashAccounts.value.length) form.cash_account_id=String(cashAccounts.value[0].id); } catch(e){error.value=e instanceof Error?e.message:'Unable to load sales returns.';} finally{loading.value=false;} }
async function submit(): Promise<void> { if(!selectedOrder.value) return; const items=selectedOrder.value.items.filter(i=>Number(form.quantities[i.id]||0)>0).map(i=>({sales_order_item_id:i.id,quantity:form.quantities[i.id]})); if(!items.length){error.value='Select at least one return quantity.';return;} saving.value=true;error.value='';try{await api('/api/sales-returns',{method:'POST',body:JSON.stringify({sales_order_id:Number(form.sales_order_id),idempotency_key:crypto.randomUUID(),return_date:form.return_date,refund_method:form.refund_method,cash_account_id:form.refund_method==='store_credit'?null:Number(form.cash_account_id),reason:form.reason,items})});success.value='Return completed. Inventory and finance ledgers have been updated.';form.sales_order_id='';form.quantities={};form.reason='';await load();}catch(e){error.value=e instanceof Error?e.message:'Unable to complete return.';}finally{saving.value=false;} }
onMounted(load);
</script>

<template>
<Head title="Sales Returns" />
<ErpLayout :user-name="props.userName" :user-email="props.userEmail">
 <div class="space-y-6 p-4 sm:p-6">
  <div class="flex flex-wrap items-center justify-between gap-3"><div><p class="text-xs font-semibold uppercase tracking-widest text-slate-500">Sales operations</p><h1 class="mt-1 text-2xl font-bold text-slate-900">Sales Returns & Refunds</h1><p class="mt-1 text-sm text-slate-500">Return fulfilled goods, restore inventory and post the refund journal.</p></div><button class="rounded-lg border px-4 py-2 text-sm" @click="load">Refresh</button></div>
  <div v-if="error" class="rounded-lg border border-red-200 bg-red-50 p-3 text-sm text-red-700">{{ error }}</div><div v-if="success" class="rounded-lg border border-emerald-200 bg-emerald-50 p-3 text-sm text-emerald-700">{{ success }}</div>
  <section v-if="can('system.sales_returns.create')" class="rounded-xl border border-slate-200 bg-white p-5 shadow-sm space-y-4">
   <h2 class="font-semibold text-slate-900">Process a sales return</h2>
   <div class="grid gap-4 md:grid-cols-3"><label class="text-sm text-slate-600">Sales order<select v-model="form.sales_order_id" class="mt-1 w-full rounded-lg border-slate-300"><option value="">Choose fulfilled order</option><option v-for="o in orders" :key="o.id" :value="String(o.id)">{{ o.order_number }} — {{ o.customer_name }}</option></select></label><label class="text-sm text-slate-600">Return date<input v-model="form.return_date" type="date" class="mt-1 w-full rounded-lg border-slate-300"></label><label class="text-sm text-slate-600">Refund method<select v-model="form.refund_method" class="mt-1 w-full rounded-lg border-slate-300"><option value="cash">Cash refund</option><option value="bank">Bank refund</option><option value="store_credit">Customer store credit</option></select></label></div>
   <div v-if="form.refund_method!=='store_credit'"><label class="text-sm text-slate-600">Refund cash/bank account<select v-model="form.cash_account_id" class="mt-1 w-full rounded-lg border-slate-300"><option value="">Choose account</option><option v-for="a in cashAccounts" :key="a.id" :value="String(a.id)">{{ a.code }} — {{ a.name }}</option></select></label></div>
   <div v-if="selectedOrder" class="overflow-x-auto rounded-lg border"><table class="w-full text-sm"><thead class="bg-slate-50 text-left text-slate-600"><tr><th class="p-3">Product</th><th class="p-3">Sold</th><th class="p-3">Returnable</th><th class="p-3">Return qty</th><th class="p-3 text-right">Unit price</th></tr></thead><tbody><tr v-for="i in selectedOrder.items" :key="i.id" class="border-t"><td class="p-3"><div class="font-medium text-slate-800">{{ i.product_name }} {{ i.variant_name||'' }}</div><div class="text-xs text-slate-500">{{ i.sku }}</div></td><td class="p-3">{{ i.quantity }}</td><td class="p-3">{{ i.returnable_quantity.toFixed(4) }}</td><td class="p-3"><input v-model="form.quantities[i.id]" type="number" min="0" :max="i.returnable_quantity" step="0.0001" class="w-28 rounded-md border-slate-300" :disabled="i.returnable_quantity<=0"></td><td class="p-3 text-right">BDT {{ Number(i.unit_price).toFixed(2) }}</td></tr></tbody></table></div>
   <label class="block text-sm text-slate-600">Reason (optional)<input v-model="form.reason" maxlength="500" class="mt-1 w-full rounded-lg border-slate-300" placeholder="Reason for return"></label>
   <div class="flex flex-wrap items-center justify-between gap-3"><div class="text-lg font-semibold">Refund total: BDT {{ total.toFixed(2) }}</div><button :disabled="saving||!selectedOrder||total<=0" class="rounded-lg bg-emerald-600 px-5 py-2.5 text-sm font-semibold text-white disabled:opacity-50" @click="submit">{{ saving?'Processing…':'Complete return & refund' }}</button></div>
   <p class="text-xs text-slate-500">Only fulfilled quantities can be returned. Each return is final, restores stock and posts an immutable journal entry.</p>
  </section>
  <section class="rounded-xl border border-slate-200 bg-white p-5 shadow-sm"><h2 class="mb-4 font-semibold">Recent return records</h2><div v-if="loading" class="py-8 text-center text-sm text-slate-500">Loading…</div><div v-else-if="!records.length" class="py-8 text-center text-sm text-slate-500">No sales returns recorded yet.</div><div v-else class="overflow-x-auto"><table class="w-full text-sm"><thead class="bg-slate-50 text-left text-slate-600"><tr><th class="p-3">Return #</th><th class="p-3">Sales order</th><th class="p-3">Date</th><th class="p-3">Method</th><th class="p-3 text-right">Refund</th><th class="p-3">Journal</th></tr></thead><tbody><tr v-for="r in records" :key="r.id" class="border-t"><td class="p-3 font-medium">{{ r.return_number }}</td><td class="p-3">{{ r.order?.order_number }}<div class="text-xs text-slate-500">{{ r.order?.customer_name }}</div></td><td class="p-3">{{ r.return_date }}</td><td class="p-3 capitalize">{{ r.refund_method.replace('_',' ') }}</td><td class="p-3 text-right">BDT {{ Number(r.refund_amount).toFixed(2) }}</td><td class="p-3">{{ r.journal_entry?.entry_number }} · {{ r.journal_entry?.status }}</td></tr></tbody></table></div></section>
 </div>
</ErpLayout>
</template>
